def validate(n: int) -> bool:
    n = abs(n)  # Handle negative numbers by taking absolute value for digit extraction
    digits_str = str(abs(n))

    count_map = {}
    for char in digits_str:
        digit = int(char)
        if digit not in count_map:
            count_map[digit] = 0
        count_map[digit] += 1

    return all(count <= d for d, count in count_map.items())
